<?php get_header(); ?>
<main id="primary" class="site-main single-post-page section"><div class="container single-post-container"><div class="single-post-layout single-layout-<?php echo esc_attr( kimpu_blog_mod( 'single_layout', 'narrow' ) ); ?><?php echo kimpu_blog_sidebar_active( true ) ? ' has-blog-sidebar' : ''; ?>" style="--blog-sidebar-width:<?php echo esc_attr( kimpu_blog_mod( 'sidebar_width', '280px' ) ); ?>"><article <?php post_class( 'single-post' ); ?>><?php while ( have_posts() ) : the_post(); ?><?php if ( kimpu_blog_mod( 'reading_progress', false ) ) { get_template_part( 'template-parts/blog/reading-progress' ); } ?><header class="single-post-header"><div class="single-post-meta"><?php get_template_part( 'template-parts/blog/post-meta' ); ?><?php if ( get_the_modified_time( 'U' ) !== get_the_time( 'U' ) ) : ?><time class="post-updated" datetime="<?php echo esc_attr( get_the_modified_date( DATE_W3C ) ); ?>"><?php printf( esc_html__( 'Updated %s', 'kimpu-multipurpose' ), esc_html( get_the_modified_date() ) ); ?></time><?php endif; ?></div><h1 class="entry-title"><?php the_title(); ?></h1></header><?php if ( kimpu_blog_mod( 'single_featured_image', true ) && has_post_thumbnail() ) : ?><figure class="single-post-image"><?php the_post_thumbnail( 'large', array( 'loading' => 'eager', 'fetchpriority' => 'high', 'decoding' => 'async', 'sizes' => '(min-width: 1024px) 840px, 100vw' ) ); ?></figure><?php endif; ?><?php $rendered_content = apply_filters( 'the_content', get_the_content() ); $toc_result = kimpu_blog_mod( 'toc_enabled', false ) ? kimpu_blog_prepare_toc_content( $rendered_content, kimpu_blog_mod( 'toc_h3', true ) ) : array( 'content' => $rendered_content, 'items' => array() ); if ( ! empty( $toc_result['items'] ) ) { get_template_part( 'template-parts/blog/table-of-contents', null, array( 'toc_items' => $toc_result['items'], 'collapsible' => kimpu_blog_mod( 'toc_collapsible', true ) ) ); } ?><div class="entry-content single-post-content"><?php echo $toc_result['content']; ?></div><?php $tags = get_the_tag_list( '', ' ', '' ); if ( $tags ) : ?><div class="post-tags"><span><?php esc_html_e( 'Tags:', 'kimpu-multipurpose' ); ?></span><?php echo wp_kses_post( $tags ); ?></div><?php endif; ?><?php if ( kimpu_blog_mod( 'share', true ) ) { get_template_part( 'template-parts/blog/post-share' ); } ?><?php if ( kimpu_blog_mod( 'author_box', true ) ) { get_template_part( 'template-parts/blog/post-author' ); } ?><?php get_template_part( 'template-parts/blog/post-navigation' ); ?><?php if ( kimpu_blog_mod( 'related_enabled', true ) ) { get_template_part( 'template-parts/blog/related-posts' ); } ?><?php if ( comments_open() || get_comments_number() ) { comments_template(); } ?><?php endwhile; ?></article><?php if ( kimpu_blog_sidebar_active( true ) ) : ?><aside class="blog-sidebar" aria-label="<?php esc_attr_e( 'Article sidebar', 'kimpu-multipurpose' ); ?>"><?php dynamic_sidebar( 'blog-sidebar' ); ?></aside><?php endif; ?></div></div></main>
<?php get_footer(); ?>
